    expect(loadData(s).recurring).toEqual([])
  })
  it('old saved data without recurring still loads', () => {
    const s = { getItem: () => JSON.stringify({ categories: DEFAULT_CATEGORIES, transactions: [], budgets: {} }) }
    expect(loadData(s).recurring).toEqual([])
